  --line: rgba(148, 163, 184, 0.18);
  --line-strong: rgba(34, 211, 238, 0.34);
  --text: #f8fafc;
  --muted: #aab6c5;
  --soft: #d7dee8;
  --cyan: #22d3ee;
  --green: #6ee7b7;
  --blue: #7aa2ff;
  --violet: #a78bfa;
  --amber: #fbbf24;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
  --radius: 24px;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--sans);
  background:
    radial-gradient(circle at 12% -10%, rgba(34, 211, 238, 0.17), transparent 35%),
    radial-gradient(circle at 88% 5%, rgba(110, 231, 183, 0.12), transparent 30%),
    linear-gradient(180deg, #0d1117 0%, #0a0f18 52%, #080b12 100%);
  color: var(--text);
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
p { color: var(--muted); line-height: 1.72; margin: 0; }
h1, h2, h3 { margin: 0; letter-spacing: -0.04em; }
h1 { font-size: clamp(3rem, 8vw, 6.9rem); line-height: 0.92; max-width: 980px; }
h2 { font-size: clamp(2rem, 4vw, 3.7rem); line-height: 1; }
h3 { font-size: 1.2rem; line-height: 1.25; }
code, pre { font-family: var(--mono); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(18px);
  background: rgba(13, 17, 23, 0.78);
  border-bottom: 1px solid var(--line);
}
.navbar {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.logo-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(110, 231, 183, 0.45);
  border-radius: 11px;
  background: linear-gradient(135deg, rgba(34, 211, 238, 0.18), rgba(110, 231, 183, 0.22));
  box-shadow: 0 0 28px rgba(34, 211, 238, 0.14);
}
.nav-links, .utility-links {
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-links a, .utility-links a, .theme-pill {
  color: var(--muted);
  font-size: 0.92rem;
  border: 1px solid transparent;
  padding: 9px 11px;
  border-radius: 999px;
  transition: 180ms ease;
}
.nav-links a:hover, .nav-links a.active, .utility-links a:hover, .theme-pill:hover {
  color: var(--text);
  border-color: var(--line);
  background: rgba(255, 255, 255, 0.045);
}
.theme-pill { cursor: default; }

.container { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }
.hero { padding: 94px 0 56px; position: relative; overflow: hidden; }
.hero.compact { padding: 70px 0 34px; }
.hero-grid { display: grid; grid-template-columns: minmax(0, 1.1fr) 360px; gap: 46px; align-items: center; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--green);
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.eyebrow::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--green); box-shadow: 0 0 20px var(--green); }
.lede { font-size: clamp(1.05rem, 2vw, 1.35rem); max-width: 790px; margin-top: 26px; color: var(--soft); }
.actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 999px;
  border: 1px solid var(--line);
  padding: 12px 18px;
  color: var(--text);
  font-weight: 750;
  transition: 180ms ease;
}
.btn.primary { color: #021114; background: linear-gradient(135deg, var(--green), var(--cyan)); border-color: transparent; box-shadow: 0 16px 46px rgba(34, 211, 238, 0.18); }
.btn:hover { transform: translateY(-2px); border-color: var(--line-strong); }
.btn.ghost { background: rgba(255,255,255,0.035); }

.terminal-card {
  border: 1px solid var(--line);
  background: rgba(3, 7, 18, 0.68);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.terminal-top { display: flex; gap: 8px; padding: 15px 17px; border-bottom: 1px solid var(--line); }
.dot { width: 10px; height: 10px; border-radius: 50%; background: #ef4444; }
.dot:nth-child(2) { background: #f59e0b; }
.dot:nth-child(3) { background: #22c55e; }
.terminal-body { padding: 22px; font-family: var(--mono); color: #d9f99d; font-size: 0.9rem; line-height: 1.8; }
.prompt { color: var(--cyan); }

.section { padding: 54px 0; }
.section-header { display: flex; justify-content: space-between; gap: 24px; align-items: end; margin-bottom: 24px; }
.section-header p { max-width: 690px; }
.grid { display: grid; gap: 18px; }
.grid.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid.cards { grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }
.card {
  position: relative;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(29, 41, 61, 0.72), rgba(15, 23, 42, 0.58));
  padding: 24px;
  min-height: 180px;
  overflow: hidden;
  transition: 180ms ease;
}
.card::after {
  content: "";
  position: absolute;
  inset: auto -30% -55% 15%;
  height: 130px;
  background: radial-gradient(circle, var(--glow, rgba(34,211,238,.16)), transparent 70%);
  pointer-events: none;
}
.card:hover { transform: translateY(-4px); border-color: var(--line-strong); background: rgba(29, 41, 61, 0.86); }
.card p { margin-top: 12px; }
.card-link { display: inline-flex; margin-top: 20px; color: var(--green); font-weight: 800; }
.icon {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: rgba(34, 211, 238, 0.1);
  border: 1px solid rgba(34, 211, 238, 0.25);
  margin-bottom: 16px;
}
.apps-card { --glow: rgba(110, 231, 183, 0.2); }
.store-card { --glow: rgba(122, 162, 255, 0.22); }
.agent-card { --glow: rgba(167, 139, 250, 0.22); }

.cli-shell {
  display: grid;
  grid-template-columns: 0.82fr 1.18fr;
  gap: 18px;
  align-items: start;
}
.accordion-list { display: grid; gap: 12px; }
.accordion-item {
  border: 1px solid var(--line);
  border-radius: 20px;
  background: rgba(15, 23, 42, 0.72);
  overflow: hidden;
}
.accordion-trigger {
  width: 100%;
  border: 0;
  color: var(--text);
  background: transparent;
  padding: 18px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  font: inherit;
  font-weight: 800;
  text-align: left;
}
.accordion-trigger span:last-child { color: var(--cyan); transition: transform 180ms ease; }
.accordion-item.open .accordion-trigger span:last-child { transform: rotate(45deg); }
.accordion-panel { display: none; padding: 0 20px 20px; color: var(--muted); }
.accordion-item.open { border-color: var(--line-strong); }
.accordion-item.open .accordion-panel { display: block; animation: reveal 180ms ease; }
.accordion-panel ol { margin: 0; padding-left: 20px; line-height: 1.85; }
@keyframes reveal { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

.code-panel {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(3, 7, 18, 0.82);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.tabs { display: flex; gap: 8px; padding: 14px; border-bottom: 1px solid var(--line); background: rgba(255,255,255,0.025); }
.tab {
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  padding: 8px 13px;
  font-weight: 800;
  cursor: pointer;
}
.tab.active { color: #021114; background: var(--green); border-color: transparent; }
.code-block { padding: 22px; }
.code-label { color: var(--muted); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.14em; font-weight: 900; margin: 0 0 10px; }
pre {
  margin: 0 0 18px;
  padding: 17px;
  border-radius: 16px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  background: #070b12;
  overflow-x: auto;
  color: #c4f1ff;
}

.docs-layout {
  width: min(1400px, calc(100% - 24px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: 284px minmax(0, 1fr);
  gap: 28px;
  padding: 28px 0 64px;
}
.sidebar {
  position: sticky;
  top: 92px;
  height: calc(100vh - 116px);
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(15, 23, 42, 0.72);
  padding: 16px;
  transition: 220ms ease;
}
.sidebar-toggle {
  width: 100%;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.04);
  color: var(--text);
  border-radius: 14px;
  padding: 11px;
  font-weight: 850;
  cursor: pointer;
  margin-bottom: 14px;
}
.sidebar-title { color: var(--green); font-size: 0.76rem; letter-spacing: 0.15em; text-transform: uppercase; font-weight: 900; margin: 10px 10px 14px; }
.sidebar nav { display: grid; gap: 5px; }
.sidebar nav a { color: var(--muted); padding: 10px; border-radius: 12px; font-size: 0.94rem; }
.sidebar nav a:hover, .sidebar nav a.active { color: var(--text); background: rgba(255,255,255,0.055); }
.docs-layout.sidebar-collapsed { grid-template-columns: 76px minmax(0, 1fr); }
.docs-layout.sidebar-collapsed .sidebar { padding: 12px; }
.docs-layout.sidebar-collapsed .sidebar-title, .docs-layout.sidebar-collapsed .sidebar nav a span { display: none; }
.docs-layout.sidebar-collapsed .sidebar nav a { text-align: center; padding: 12px 4px; }
.docs-layout.sidebar-collapsed .sidebar-toggle { font-size: 0; }
.docs-layout.sidebar-collapsed .sidebar-toggle::after { content: "☰"; font-size: 1rem; }
.doc-main { min-width: 0; }
.doc-section {
  border: 1px solid var(--line);
  border-radius: 28px;
  background: rgba(15, 23, 42, 0.48);
  padding: clamp(24px, 4vw, 42px);
  margin-bottom: 22px;
}
.doc-section > p { margin-top: 14px; max-width: 860px; }

.kicker { color: var(--cyan); font-size: 0.78rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 900; margin-bottom: 10px; }
.list { display: grid; gap: 12px; margin-top: 22px; }
.list-item {
  display: flex;
  gap: 14px;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 18px;
  background: rgba(255,255,255,0.032);
}
.check { color: var(--green); font-weight: 900; }
.actor-diagram {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 24px;
}
.actor { text-align: center; min-height: 160px; }
.actor strong { display: block; font-size: 1.4rem; margin-top: 12px; }
.status { display: inline-flex; color: #171004; background: var(--amber); border-radius: 999px; padding: 7px 10px; font-weight: 900; margin-top: 18px; }

.footer {
  border-top: 1px solid var(--line);
  background: rgba(3, 7, 18, 0.48);
  padding: 42px 0;
  margin-top: 40px;
}
.footer-grid { display: grid; grid-template-columns: 1.2fr repeat(4, 1fr); gap: 22px; }
.footer h4 { margin: 0 0 12px; color: var(--text); }
.footer a { display: block; color: var(--muted); margin: 9px 0; font-size: 0.92rem; }
.footer a:hover { color: var(--green); }

.mobile-menu { display: none; }

@media (max-width: 940px) {
  .navbar { flex-wrap: wrap; padding: 12px 0; }
  .nav-links { order: 3; width: 100%; overflow-x: auto; padding-bottom: 4px; }
  .utility-links { display: none; }
  .hero-grid, .cli-shell, .grid.three, .grid.two { grid-template-columns: 1fr; }
  .docs-layout { grid-template-columns: 1fr; }
  .sidebar { position: relative; top: auto; height: auto; }
  .docs-layout.sidebar-collapsed { grid-template-columns: 1fr; }
  .docs-layout.sidebar-collapsed .sidebar nav { display: none; }
  .actor-diagram { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 620px) {
  h1 { font-size: 3.2rem; }
  .container, .navbar { width: min(100% - 22px, 1180px); }
  .hero { padding-top: 58px; }
  .section-header { display: block; }
  .card, .doc-section { border-radius: 20px; }
  .actor-diagram, .footer-grid { grid-template-columns: 1fr; }
  .actions .btn { width: 100%; }
}
EOF

cat > /app/output/script.js <<'EOF'
document.addEventListener('DOMContentLoaded', () => {
  const installCommands = {
    npm: 'npm i -g @commerceforge/cli@latest',
    yarn: 'yarn global add @commerceforge/cli@latest',
    pnpm: 'pnpm add -g @commerceforge/cli@latest'
  };

  const initCommands = {
    apps: 'commerceforge app init',
    themes: 'commerceforge theme init',
    headless: 'commerceforge hydrogen init'
  };

  let packageManager = 'npm';
  let activeAccordion = document.querySelector('.accordion-item.open')?.dataset.target || 'apps';

  const installCode = document.querySelector('[data-install-code]');
  const initCode = document.querySelector('[data-init-code]');

  function syncCode() {
    if (installCode) installCode.textContent = installCommands[packageManager];
    if (initCode) initCode.textContent = initCommands[activeAccordion];
  }

  document.querySelectorAll('.tab').forEach((tab) => {
    tab.addEventListener('click', () => {
      packageManager = tab.dataset.package;
      document.querySelectorAll('.tab').forEach((button) => button.classList.toggle('active', button === tab));
      syncCode();
    });
  });

  document.querySelectorAll('.accordion-trigger').forEach((trigger) => {
    trigger.addEventListener('click', () => {
      const item = trigger.closest('.accordion-item');
      activeAccordion = item.dataset.target;
      document.querySelectorAll('.accordion-item').forEach((candidate) => {
        const isActive = candidate === item;
        candidate.classList.toggle('open', isActive);
        candidate.querySelector('.accordion-trigger')?.setAttribute('aria-expanded', String(isActive));
      });
      syncCode();
    });
  });

  document.querySelectorAll('[data-sidebar-toggle]').forEach((button) => {
    button.addEventListener('click', () => {
      const layout = button.closest('.docs-layout');
      const collapsed = layout.classList.toggle('sidebar-collapsed');
      button.textContent = collapsed ? 'Expand sidebar' : 'Collapse sidebar';
      button.setAttribute('aria-expanded', String(!collapsed));
    });
  });

  syncCode();
});
EOF

